import subprocess, json, sys

scenarios = ["normal", "mixed", "partial-zero", "empty", "unknown", "fail-fast", "cancelled", "live"]
results = {}
for sc in scenarios:
    kwargs = dict(capture_output=True, text=True, timeout=10)
    if sc == "live":
        p = subprocess.run([sys.executable, "/work/batch.py", sc], input="\n", **kwargs)
    else:
        p = subprocess.run([sys.executable, "/work/batch.py", sc], **kwargs)
    results[sc] = p
    print("=== ", sc, " exit=", p.returncode)
    for line in p.stderr.strip().splitlines():
        print(" STDERR:", line)
    print(" STDOUT:", p.stdout.strip())
    print()

